import{_ as e,c as r,o as h,ah as i}from"./chunks/framework.Dnh4IO1K.js";const p=JSON.parse('{"title":"無妄","description":"焦氏易林注 - 無妄","frontmatter":{"title":"無妄","description":"焦氏易林注 - 無妄"},"headers":[],"relativePath":"classics/jiaoyilin/025.md","filePath":"classics/jiaoyilin/025.md"}'),l={name:"classics/jiaoyilin/025.md"};function n(d,a,t,o,s,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="無妄" tabindex="-1">無妄 <a class="header-anchor" href="#無妄" aria-label="Permalink to “無妄”">​</a></h1><h3 id="無妄-1" tabindex="-1">無妄 <a class="header-anchor" href="#無妄-1" aria-label="Permalink to “無妄”">​</a></h3><h3 id="無妄之乾" tabindex="-1">無妄之乾 <a class="header-anchor" href="#無妄之乾" aria-label="Permalink to “無妄之乾”">​</a></h3><h3 id="林辭" tabindex="-1">林辭 <a class="header-anchor" href="#林辭" aria-label="Permalink to “林辭”">​</a></h3><p>儋耳穿胸，僵離旁舂。天地易紀，日月更始。蝮螫我手，痛為吾毒。</p><h3 id="注" tabindex="-1">注 <a class="header-anchor" href="#注" aria-label="Permalink to “注”">​</a></h3><p>詳《師》之《謙》。○第二句依《師》之《謙》校改，各本皆作&quot;緾離勞舂&quot;，非，《漢書武帝紀》：&quot;定越地曰珠崖儋耳&quot;。</p><h3 id="無妄之坤" tabindex="-1">無妄之坤 <a class="header-anchor" href="#無妄之坤" aria-label="Permalink to “無妄之坤”">​</a></h3><h3 id="林辭-1" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-1" aria-label="Permalink to “林辭”">​</a></h3><p>慈母之恩，長大無孫。消息襁褓，害不入門。</p><h3 id="注-1" tabindex="-1">注 <a class="header-anchor" href="#注-1" aria-label="Permalink to “注”">​</a></h3><p>此用《無妄》象。乾為恩，巽為母、為長，乾為大，艮為孫，巽隕落，故曰無孫。巽為襁褓、為入，乾為門。</p><h3 id="無妄之屯" tabindex="-1">無妄之屯 <a class="header-anchor" href="#無妄之屯" aria-label="Permalink to “無妄之屯”">​</a></h3><h3 id="林辭-2" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-2" aria-label="Permalink to “林辭”">​</a></h3><p>訛言妄語，轉相詿誤。道左失跡，不知狼處。</p><h3 id="注-2" tabindex="-1">注 <a class="header-anchor" href="#注-2" aria-label="Permalink to “注”">​</a></h3><p>震為言，初至五正覆震相背故曰訛妄、曰詿誤。震為道、為左、為跡，坎伏故失跡、故不知狼處。艮為狼也。○狼，宋元本作鄉，依汲古。</p><h3 id="無妄之蒙" tabindex="-1">無妄之蒙 <a class="header-anchor" href="#無妄之蒙" aria-label="Permalink to “無妄之蒙”">​</a></h3><h3 id="林辭-3" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-3" aria-label="Permalink to “林辭”">​</a></h3><p>鬱映不明，陰積無光。日在北陸，萬物雕藏。</p><h3 id="注-3" tabindex="-1">注 <a class="header-anchor" href="#注-3" aria-label="Permalink to “注”">​</a></h3><p>艮為光明，坤坎皆黑，故曰鬱映、曰無光，坤為陰、為積。艮為日，坤為陸，位北，故曰北陸。坤為萬物，坤死故雕藏。《左傳》：&quot;日在北陸而藏冰&quot;，言冬日也。○映，宋元本作快，依汲古。映，音決，日食色。鬱映，言黑暗也。</p><h3 id="無妄之需" tabindex="-1">無妄之需 <a class="header-anchor" href="#無妄之需" aria-label="Permalink to “無妄之需”">​</a></h3><h3 id="林辭-4" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-4" aria-label="Permalink to “林辭”">​</a></h3><p>王母多福，天祿所伏。君之寵光，君子有昌。</p><h3 id="注-4" tabindex="-1">注 <a class="header-anchor" href="#注-4" aria-label="Permalink to “注”">​</a></h3><p>乾為王，伏坤為母，故曰王母。王母，大母也。乾為福、為天祿，坎為伏，乾為君、為寵，離為光，乾為君子。○君，汲古作居，光作昌，昌作光，今依宋元本。</p><h3 id="無妄之訟" tabindex="-1">無妄之訟 <a class="header-anchor" href="#無妄之訟" aria-label="Permalink to “無妄之訟”">​</a></h3><h3 id="林辭-5" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-5" aria-label="Permalink to “林辭”">​</a></h3><p>不耕而獲，家食不給。中女無良，長子跛足。疏齒善市，商人有喜。</p><h3 id="注-5" tabindex="-1">注 <a class="header-anchor" href="#注-5" aria-label="Permalink to “注”">​</a></h3><p>震為耕、為獲，震伏，故曰不耕。伏坤為飢，故曰不給。離為中女，離惡故曰無良。震為長子、為足，坎蹇故曰跛足。兌為齒，震比兌形長故曰疏齒。巽為市，震為商人、為喜。○跛，宋元本作徒，依汲古。按：此多用伏象。</p><h3 id="無妄之師" tabindex="-1">無妄之師 <a class="header-anchor" href="#無妄之師" aria-label="Permalink to “無妄之師”">​</a></h3><h3 id="林辭-6" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-6" aria-label="Permalink to “林辭”">​</a></h3><p>火起上門，不為我殘。跳脫東西，獨得生完。不利出鄰，疾病憂患。</p><h3 id="注-6" tabindex="-1">注 <a class="header-anchor" href="#注-6" aria-label="Permalink to “注”">​</a></h3><p>伏離為火，乾為門戶，故曰上門。震為跳脫、為東、為生，坎為西，坎險故不利，故病憂。震為鄰。</p><h3 id="無妄之比" tabindex="-1">無妄之比 <a class="header-anchor" href="#無妄之比" aria-label="Permalink to “無妄之比”">​</a></h3><h3 id="林辭-7" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-7" aria-label="Permalink to “林辭”">​</a></h3><p>持刀操肉，對酒不食。夫亡從軍，少子入獄。抱膝獨宿。</p><h3 id="注-7" tabindex="-1">注 <a class="header-anchor" href="#注-7" aria-label="Permalink to “注”">​</a></h3><p>詳《復》之《剝》。○少，宋元本作長，非，依汲古。</p><h3 id="無妄之小畜" tabindex="-1">無妄之小畜 <a class="header-anchor" href="#無妄之小畜" aria-label="Permalink to “無妄之小畜”">​</a></h3><h3 id="林辭-8" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-8" aria-label="Permalink to “林辭”">​</a></h3><p>鰌鰕去海，遊於枯裡。街巷迫狹，不得自在。南北四極，渴餒成疾。</p><h3 id="注-8" tabindex="-1">注 <a class="header-anchor" href="#注-8" aria-label="Permalink to “注”">​</a></h3><p>巽為魚，乾為海，巽在外，故曰去海。離為枯，伏坤為裡。離中虛，故為街巷、為迫狹。離為南，伏坎為北，坤為餒、為疾，《易睽九二》雲&quot;遇主於巷&quot;，即以上離為巷。</p><h3 id="無妄之履" tabindex="-1">無妄之履 <a class="header-anchor" href="#無妄之履" aria-label="Permalink to “無妄之履”">​</a></h3><h3 id="林辭-9" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-9" aria-label="Permalink to “林辭”">​</a></h3><p>啞啞笑語，與歡飲酒。長樂行觴，千秋起舞，拜受大福。</p><h3 id="注-9" tabindex="-1">注 <a class="header-anchor" href="#注-9" aria-label="Permalink to “注”">​</a></h3><p>通《謙》。震為啞啞、為笑語、為歡，坎為酒，震為觴、為長樂、為起舞，兌為秋，乾為千，故曰千秋。艮手為拜，震為福。○笑語，宋元本作喜笑，今依汲古。</p><h3 id="無妄之泰" tabindex="-1">無妄之泰 <a class="header-anchor" href="#無妄之泰" aria-label="Permalink to “無妄之泰”">​</a></h3><h3 id="林辭-10" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-10" aria-label="Permalink to “林辭”">​</a></h3><p>登高上山，賓於四門。士伍得歡，福為我根。</p><h3 id="注-10" tabindex="-1">注 <a class="header-anchor" href="#注-10" aria-label="Permalink to “注”">​</a></h3><p>震為登，伏巽為高，艮為山、為門，震為賓，坤為師、為士伍，震為歡、為福，坤為我。○士伍，宋元本作吾士，茲依汲古。</p><h3 id="無妄之否" tabindex="-1">無妄之否 <a class="header-anchor" href="#無妄之否" aria-label="Permalink to “無妄之否”">​</a></h3><h3 id="林辭-11" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-11" aria-label="Permalink to “林辭”">​</a></h3><p>天厭周德，命我南國。以禮靜民，兵革休息。</p><h3 id="注-11" tabindex="-1">注 <a class="header-anchor" href="#注-11" aria-label="Permalink to “注”">​</a></h3><p>厭，滿足也。乾為天、為周，天厭周德，即天與周德。巽為命，坤為我、為國，乾南故曰南國。坤為禮、為民，艮為兵革，艮止故休息。○命我，汲古作命與，依宋元本。</p><h3 id="無妄之同人" tabindex="-1">無妄之同人 <a class="header-anchor" href="#無妄之同人" aria-label="Permalink to “無妄之同人”">​</a></h3><h3 id="林辭-12" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-12" aria-label="Permalink to “林辭”">​</a></h3><p>壅遏堤防，水不得行。火光盛陽，陰霓伏藏，走歸其鄉。</p><h3 id="注-12" tabindex="-1">注 <a class="header-anchor" href="#注-12" aria-label="Permalink to “注”">​</a></h3><p>通《師》。坤閉故為壅遏、為堤防，下與坎遇故曰水不得行。離為火、為光，坎為陰霓、為伏，震為走、為歸，坤為鄉。○霓，汲古作魄，依宋元本。</p><h3 id="無妄之大有" tabindex="-1">無妄之大有 <a class="header-anchor" href="#無妄之大有" aria-label="Permalink to “無妄之大有”">​</a></h3><h3 id="林辭-13" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-13" aria-label="Permalink to “林辭”">​</a></h3><p>河海都市，國之奧府。商人受福，少子玉食。</p><h3 id="注-13" tabindex="-1">注 <a class="header-anchor" href="#注-13" aria-label="Permalink to “注”">​</a></h3><p>通《比》。坤為河海、為都市、為國、為奧府，艮為少子，兌為食，乾為玉，故曰玉食。</p><h3 id="無妄之謙" tabindex="-1">無妄之謙 <a class="header-anchor" href="#無妄之謙" aria-label="Permalink to “無妄之謙”">​</a></h3><h3 id="林辭-14" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-14" aria-label="Permalink to “林辭”">​</a></h3><p>東行避兵，南去不祥。西逐兇惡，北迎福生，與喜相逢。</p><h3 id="注-14" tabindex="-1">注 <a class="header-anchor" href="#注-14" aria-label="Permalink to “注”">​</a></h3><p>震為東行，艮為刀兵，坎為避，故曰東行避兵。震為南，在外故去不祥。坎為西，震為逐，坤為兇惡，故曰西逐兇惡，言坎遇坤也。坎為北，震為福喜。○迎，汲古作逃，非，依宋元本。</p><h3 id="無妄之豫" tabindex="-1">無妄之豫 <a class="header-anchor" href="#無妄之豫" aria-label="Permalink to “無妄之豫”">​</a></h3><h3 id="林辭-15" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-15" aria-label="Permalink to “林辭”">​</a></h3><p>東家中女，嫫母最醜。三十無室，媒伯勞苦。</p><h3 id="注-15" tabindex="-1">注 <a class="header-anchor" href="#注-15" aria-label="Permalink to “注”">​</a></h3><p>震為東，艮為家，伏離為中女，坤為母、為醜，故曰嫫母。嫫母，黃帝妃貌醜。震數三，坤數十，艮為室，坤寡，故曰三十無室。坎為和、為媒，震為伯，坎為勞苦。</p><h3 id="無妄之隨" tabindex="-1">無妄之隨 <a class="header-anchor" href="#無妄之隨" aria-label="Permalink to “無妄之隨”">​</a></h3><h3 id="林辭-16" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-16" aria-label="Permalink to “林辭”">​</a></h3><p>破亡之國，天所不福，難以止息。</p><h3 id="注-16" tabindex="-1">注 <a class="header-anchor" href="#注-16" aria-label="Permalink to “注”">​</a></h3><p>兌毀折故曰破亡。艮為國、為天、為止息。</p><h3 id="無妄之蠱" tabindex="-1">無妄之蠱 <a class="header-anchor" href="#無妄之蠱" aria-label="Permalink to “無妄之蠱”">​</a></h3><h3 id="林辭-17" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-17" aria-label="Permalink to “林辭”">​</a></h3><p>驂駕蹇驢，日暮失時。居者無憂，保我樂娛。</p><h3 id="注-17" tabindex="-1">注 <a class="header-anchor" href="#注-17" aria-label="Permalink to “注”">​</a></h3><p>震為驂駕、為馬，艮小故曰驢，兌折故曰蹇驢。艮為日，兌為昧、為暮，艮為時，兌折故曰失時。艮為居、為保，震為樂。</p><h3 id="無妄之臨" tabindex="-1">無妄之臨 <a class="header-anchor" href="#無妄之臨" aria-label="Permalink to “無妄之臨”">​</a></h3><h3 id="林辭-18" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-18" aria-label="Permalink to “林辭”">​</a></h3><p>蝃蝀充側，佞幸傾惑。女謁橫行，正道雍塞。</p><h3 id="注-18" tabindex="-1">注 <a class="header-anchor" href="#注-18" aria-label="Permalink to “注”">​</a></h3><p>詳《蠱》之《復》。○充，汲古作之。正道雍塞，汲古作王道充塞，非，今依宋元本。</p><h3 id="無妄之觀" tabindex="-1">無妄之觀 <a class="header-anchor" href="#無妄之觀" aria-label="Permalink to “無妄之觀”">​</a></h3><h3 id="林辭-19" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-19" aria-label="Permalink to “林辭”">​</a></h3><p>三羖五牂，相隨並行。迷入空澤，循谷直北。徑涉六駁，為所傷賊。</p><h3 id="注-19" tabindex="-1">注 <a class="header-anchor" href="#注-19" aria-label="Permalink to “注”">​</a></h3><p>通《大壯》。兌為羊，故曰羖、曰牂，艮數三，巽卦數五，故曰三羖五牂。震為行，坤為迷，兌為澤，坤虛故曰空澤。艮為谷，坤為北，艮為駁，伏乾數六，故曰六駁。《詩秦風》：&quot;隰有六駁&quot;，疏：陸機雲：駁馬，梓榆也，其樹青白皮，駁犖遙視似駁馬，據是是六駁為木，徑涉六駁者，言循谷走，經厯林木，為雜樹所傷也。若作獸詁，則徑涉不合矣，然則《焦詁》六駁正與陸合，與毛鄭異也。巽伏為賊。○徑，汲古作經，依宋元本。</p><h3 id="無妄之噬嗑" tabindex="-1">無妄之噬嗑 <a class="header-anchor" href="#無妄之噬嗑" aria-label="Permalink to “無妄之噬嗑”">​</a></h3><h3 id="林辭-20" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-20" aria-label="Permalink to “林辭”">​</a></h3><p>戴喜抱子，與利為友。天之所命，不憂危殆。荀伯勞苦，西來王母。</p><h3 id="注-20" tabindex="-1">注 <a class="header-anchor" href="#注-20" aria-label="Permalink to “注”">​</a></h3><p>震為喜、為子，艮為戴、為抱、為友，伏巽為利，震巽同聲，故曰與利為友。艮為天，巽為命，坎為憂、為危殆，震喜故不憂殆。荀伯，晉荀躒也，城成周，定王室，故詩美之曰郇伯勞之。荀即郇國後也，與毛鄭說異。震為伯，坎為勞、為西，震為王，伏巽為母。○戴，宋元作載。荀，宋元本作●，均依汲古。殆，音以。</p><h3 id="無妄之賁" tabindex="-1">無妄之賁 <a class="header-anchor" href="#無妄之賁" aria-label="Permalink to “無妄之賁”">​</a></h3><h3 id="林辭-21" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-21" aria-label="Permalink to “林辭”">​</a></h3><p>織縷未就，針折不復。女工多能，亂我政事。</p><h3 id="注-21" tabindex="-1">注 <a class="header-anchor" href="#注-21" aria-label="Permalink to “注”">​</a></h3><p>伏巽為縷，艮手為織，坎為針、為折。巽為女工，離為亂。○第二句宋元本作&quot;勝折無後&quot;，依汲古。能，汲古作態，依宋元本。</p><h3 id="無妄之剝" tabindex="-1">無妄之剝 <a class="header-anchor" href="#無妄之剝" aria-label="Permalink to “無妄之剝”">​</a></h3><h3 id="林辭-22" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-22" aria-label="Permalink to “林辭”">​</a></h3><p>行露之訟，貞女不行。君子無食，使道壅塞。</p><h3 id="注-22" tabindex="-1">注 <a class="header-anchor" href="#注-22" aria-label="Permalink to “注”">​</a></h3><p>行露，《召南》篇名，美女能以禮自守也。坤為霜、為露，震為言，艮為反震，《左傳》謂為敗言故曰訟。艮為貞，坤女艮止故不行。艮為君子，坤飢故無食。艮為道，坤為積聚，故曰壅塞。○元本作《復》林。</p><h3 id="無妄之復" tabindex="-1">無妄之復 <a class="header-anchor" href="#無妄之復" aria-label="Permalink to “無妄之復”">​</a></h3><h3 id="林辭-23" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-23" aria-label="Permalink to “林辭”">​</a></h3><p>羿張烏號，彀射天狼。鐘鼓不鳴，將軍振旅。趙國雄勇，鬬死滎陽。</p><h3 id="注-23" tabindex="-1">注 <a class="header-anchor" href="#注-23" aria-label="Permalink to “注”">​</a></h3><p>詳《噬嗑》之《旅》。此多二三兩句，震為鐘鼓、為鳴，坤閉故不鳴。坤為師、為軍，震為振。○旅，汲古作攘，依宋元本。趙國或為人名，未必為訛字。《噬嗑》之《旅》同他林有作柱者，亦未必是。</p><h3 id="無妄之無妄" tabindex="-1">無妄之無妄 <a class="header-anchor" href="#無妄之無妄" aria-label="Permalink to “無妄之無妄”">​</a></h3><h3 id="林辭-24" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-24" aria-label="Permalink to “林辭”">​</a></h3><p>夏臺羑里，湯文卮處。皋陶聽理，岐人悅喜。西望華首，東歸無咎。</p><h3 id="注-24" tabindex="-1">注 <a class="header-anchor" href="#注-24" aria-label="Permalink to “注”">​</a></h3><p>艮為臺，納丙，故曰夏臺。艮為裡、為道，故曰羑里。羑，道也。乾為王，故曰湯文。艮為拘，巽為系，故曰卮處。昔桀囚成湯於夏臺，紂囚文王於羑里也。艮為皋、為岐山，震為樂、為陶、為人，故曰岐人悅喜。伏兌為西，艮為望、為華嶽。乾為首，震為東、為歸。○理，汲古作斷，依宋元本。首，宋元本作夏，依汲古。首與咎韻。</p><h3 id="無妄之大畜" tabindex="-1">無妄之大畜 <a class="header-anchor" href="#無妄之大畜" aria-label="Permalink to “無妄之大畜”">​</a></h3><h3 id="林辭-25" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-25" aria-label="Permalink to “林辭”">​</a></h3><p>延頸望酒，不入我口。商人勞苦，利得無有。夏臺羑里，雖危復喜。</p><h3 id="注-25" tabindex="-1">注 <a class="header-anchor" href="#注-25" aria-label="Permalink to “注”">​</a></h3><p>艮為頸、為望，坎為酒，此無《坎》象，疑以兌澤為酒也。兌為口，震為商人，伏巽為利，艮為臺，納丙故曰夏臺。艮為裡，兌折為危，震為喜。湯囚夏臺，文囚羑里。○雖危，汲古作難為，依宋元本。</p><h3 id="無妄之頤" tabindex="-1">無妄之頤 <a class="header-anchor" href="#無妄之頤" aria-label="Permalink to “無妄之頤”">​</a></h3><h3 id="林辭-26" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-26" aria-label="Permalink to “林辭”">​</a></h3><p>冠帶南遊，與喜相期。邀於嘉國，拜位逢時。</p><h3 id="注-26" tabindex="-1">注 <a class="header-anchor" href="#注-26" aria-label="Permalink to “注”">​</a></h3><p>艮為冠，伏巽為帶，震為南、為遊、為喜、為嘉，坤為國，艮為拜、為位、為時。○邀於嘉國，元本作僥於家國，依宋本、汲古。位，元本作為，依汲古。</p><h3 id="無妄之大過" tabindex="-1">無妄之大過 <a class="header-anchor" href="#無妄之大過" aria-label="Permalink to “無妄之大過”">​</a></h3><h3 id="林辭-27" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-27" aria-label="Permalink to “林辭”">​</a></h3><p>東西觸垣，不利出門。魚藏深水，無以樂賓。爵級摧頹，光威減衰。</p><h3 id="注-27" tabindex="-1">注 <a class="header-anchor" href="#注-27" aria-label="Permalink to “注”">​</a></h3><p>伏震為東，兌西，艮為垣，震為觸，《頤》正反艮，故曰東西觸垣。巽為利，艮為門，巽為魚，坤為深水，震為賓、為樂，言魚藏水底難得，不能饗賓，故曰無以樂賓。震為爵，坤喪，故曰摧頹、曰減衰。艮為光，震為威，故曰光威減衰。○減，汲古作鹹，依宋元本。</p><h3 id="無妄之坎" tabindex="-1">無妄之坎 <a class="header-anchor" href="#無妄之坎" aria-label="Permalink to “無妄之坎”">​</a></h3><h3 id="林辭-28" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-28" aria-label="Permalink to “林辭”">​</a></h3><p>兩母十子，轉息無已。五乳百雛，騂駁驪駒。</p><h3 id="注-28" tabindex="-1">注 <a class="header-anchor" href="#注-28" aria-label="Permalink to “注”">​</a></h3><p>通《離》。互巽為母，兌數二，故曰兩母。震為子，兌數十，故曰十子。震為生，正反震，故曰轉息無已。艮為乳，坎數五，故曰五乳。震為百、為雛、為馬，故曰驪駒。震為玄黃，故曰騂駁。騂，馬色赤黃。駁，馬色不純也。○駁，宋元作駁，依汲古。</p><h3 id="無妄之離" tabindex="-1">無妄之離 <a class="header-anchor" href="#無妄之離" aria-label="Permalink to “無妄之離”">​</a></h3><h3 id="林辭-29" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-29" aria-label="Permalink to “林辭”">​</a></h3><p>重黎祖後，司馬太史。陽氏之災，雕宮悲苦。</p><h3 id="注-29" tabindex="-1">注 <a class="header-anchor" href="#注-29" aria-label="Permalink to “注”">​</a></h3><p>丁雲：太史公自序：&quot;昔在顓頊，命南正重以司天，北正黎以司地，當周宣王時，失其守而為司馬氏&quot;，首二句言重祖、黎祖之後為司馬氏、為太史公也。離南坎北，故曰重黎。伏艮為祖，震為馬、為言、為太史。太史，紀言之官也。○陽，宋元本作陸，依汲古。春秋時晉殺陽處父故曰災。林或指此。宮，宋元本作害，依汲古。</p><h3 id="無妄之鹹" tabindex="-1">無妄之鹹 <a class="header-anchor" href="#無妄之鹹" aria-label="Permalink to “無妄之鹹”">​</a></h3><h3 id="林辭-30" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-30" aria-label="Permalink to “林辭”">​</a></h3><p>內執柔德，止訟以嘿。宗邑賴福，禍災不作。</p><h3 id="注-30" tabindex="-1">注 <a class="header-anchor" href="#注-30" aria-label="Permalink to “注”">​</a></h3><p>通《損》。伏坤為柔，二至上正覆震，故曰訟，艮止故嘿。乾為宗，坤為邑、為禍災，震福故不災。</p><h3 id="無妄之恆" tabindex="-1">無妄之恆 <a class="header-anchor" href="#無妄之恆" aria-label="Permalink to “無妄之恆”">​</a></h3><h3 id="林辭-31" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-31" aria-label="Permalink to “林辭”">​</a></h3><p>採唐沫鄉，邀期桑中。失信不會，憂思約帶。</p><h3 id="注-31" tabindex="-1">注 <a class="header-anchor" href="#注-31" aria-label="Permalink to “注”">​</a></h3><p>詳《師》之《噬嗑》。</p><h3 id="無妄之遯" tabindex="-1">無妄之遯 <a class="header-anchor" href="#無妄之遯" aria-label="Permalink to “無妄之遯”">​</a></h3><h3 id="林辭-32" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-32" aria-label="Permalink to “林辭”">​</a></h3><p>官成立政，衣就缺袂。恭儉為衛，終無禍尤。</p><h3 id="注-32" tabindex="-1">注 <a class="header-anchor" href="#注-32" aria-label="Permalink to “注”">​</a></h3><p>艮為官、為成，乾為衣，震為袂，震伏故缺。艮為恭儉、為終，坤為禍尤，坤伏故無。○官，宋元本作宮，依汲古。</p><h3 id="無妄之大壯" tabindex="-1">無妄之大壯 <a class="header-anchor" href="#無妄之大壯" aria-label="Permalink to “無妄之大壯”">​</a></h3><h3 id="林辭-33" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-33" aria-label="Permalink to “林辭”">​</a></h3><p>麒麟鳳凰，子孫盛昌。少齊在門，利以合婚。振衣彈冠，貴人大歡。</p><h3 id="注-33" tabindex="-1">注 <a class="header-anchor" href="#注-33" aria-label="Permalink to “注”">​</a></h3><p>對《觀》。坤為文，故曰麒麟鳳凰。艮為子孫，震為盛昌，巽為齊，艮少故曰少齊。《左傳昭二年》：&quot;韓須如齊，逆女少薑，少薑寵，晉人謂之少齊&quot;是也。艮為門，巽為利，坤為衣，艮為冠、為振、為彈、為貴人，震為歡。○第五句依宋元本補，汲古無。大，宋元本作所，依汲古。</p><h3 id="無妄之晉" tabindex="-1">無妄之晉 <a class="header-anchor" href="#無妄之晉" aria-label="Permalink to “無妄之晉”">​</a></h3><h3 id="林辭-34" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-34" aria-label="Permalink to “林辭”">​</a></h3><p>亂危之國，不可涉域。機發身頓，遂至僵覆。</p><h3 id="注-34" tabindex="-1">注 <a class="header-anchor" href="#注-34" aria-label="Permalink to “注”">​</a></h3><p>離為亂，坎為危，坤為國、為域，震為涉，震覆艮止，故不可涉。坎為機，坤為身、為死，故曰頓。《釋名》頓，僵也。○下二句汲古作&quot;機機發發，身頓僵覆&quot;，今依宋元本。</p><h3 id="無妄之明夷" tabindex="-1">無妄之明夷 <a class="header-anchor" href="#無妄之明夷" aria-label="Permalink to “無妄之明夷”">​</a></h3><h3 id="林辭-35" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-35" aria-label="Permalink to “林辭”">​</a></h3><p>千雀萬鳩，與鷂為仇。威勢不敵，雖眾無益，為鷹所擊。</p><h3 id="注-35" tabindex="-1">注 <a class="header-anchor" href="#注-35" aria-label="Permalink to “注”">​</a></h3><p>坤為千萬，離為雀鳩，反艮為鷹鷂。坎為仇，震為威，坎為眾，反艮首向下故曰為鷹所擊。○勢，宋元本訛挈，茲依汲古。汲古下多&quot;萬事皆失&quot;四字，依宋本刪。</p><h3 id="無妄之家人" tabindex="-1">無妄之家人 <a class="header-anchor" href="#無妄之家人" aria-label="Permalink to “無妄之家人”">​</a></h3><h3 id="林辭-36" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-36" aria-label="Permalink to “林辭”">​</a></h3><p>眾神集聚，相與議語。南國虐亂，百姓愁苦。興師徵討，更立聖主。</p><h3 id="注-36" tabindex="-1">注 <a class="header-anchor" href="#注-36" aria-label="Permalink to “注”">​</a></h3><p>詳《屯》之《節》。○聖，汲古作賢，依宋元本。坎為聖也。</p><h3 id="無妄之睽" tabindex="-1">無妄之睽 <a class="header-anchor" href="#無妄之睽" aria-label="Permalink to “無妄之睽”">​</a></h3><h3 id="林辭-37" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-37" aria-label="Permalink to “林辭”">​</a></h3><p>顏淵閔騫，以禮自閑。君子所居，禍災不存。</p><h3 id="注-37" tabindex="-1">注 <a class="header-anchor" href="#注-37" aria-label="Permalink to “注”">​</a></h3><p>通《蹇》。艮為顏，坎為淵、為悲閔，艮手為騫，故曰顏淵閔騫。艮為閑、為君子、為居，坎為禍，在外，故曰不存。</p><h3 id="無妄之蹇" tabindex="-1">無妄之蹇 <a class="header-anchor" href="#無妄之蹇" aria-label="Permalink to “無妄之蹇”">​</a></h3><h3 id="林辭-38" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-38" aria-label="Permalink to “林辭”">​</a></h3><p>三桓子孫，世秉國權。爵世上卿，富於周公。</p><h3 id="注-38" tabindex="-1">注 <a class="header-anchor" href="#注-38" aria-label="Permalink to “注”">​</a></h3><p>桓，木名。艮為木，離卦數三，故曰三桓。艮為子孫，艮手為秉，秉，持也。艮為國、為爵、為上卿，遇卦&quot;無妄&quot;震為周、為公，乾為富。魯季孫、孟孫、叔孫，皆桓公後，故曰三桓，與魯相終始也。○爵世，汲古作爵勢，依元本。《論語》：&quot;季氏富於周公&quot;。</p><h3 id="無妄之解" tabindex="-1">無妄之解 <a class="header-anchor" href="#無妄之解" aria-label="Permalink to “無妄之解”">​</a></h3><h3 id="林辭-39" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-39" aria-label="Permalink to “林辭”">​</a></h3><p>鶴鳴九皋，處子失時。載土販鹽，難為功巧。</p><h3 id="注-39" tabindex="-1">注 <a class="header-anchor" href="#注-39" aria-label="Permalink to “注”">​</a></h3><p>震為鶴、為鳴，數九故曰九皋。鶴鳴，《小雅》篇名，毛謂教宣王求賢，茲曰處子失時，義與毛異。巽為伏，故為處子。震為載、為商販，坎為土，坎土象後，只邵子與《易林》同，他未見也。鹽象，《說文》：&quot;古宿沙煮海水為鹽&quot;，鹽，鹹也。又按：《洪範》：&quot;水潤下作鹹&quot;，疑仍坎水象。卦有重坎，故既曰土又曰鹽。○巧，汲古作力，依宋元本。子為土之訛。</p><h3 id="無妄之損" tabindex="-1">無妄之損 <a class="header-anchor" href="#無妄之損" aria-label="Permalink to “無妄之損”">​</a></h3><h3 id="林辭-40" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-40" aria-label="Permalink to “林辭”">​</a></h3><p>方軸圓輪，車行不前。組囊以錐，失其事便。還師振旅，兵革休止。</p><h3 id="注-40" tabindex="-1">注 <a class="header-anchor" href="#注-40" aria-label="Permalink to “注”">​</a></h3><p>坤為方、為軸，伏乾為圓，故曰方軸圓輪。震為車、為行，艮止故不前。坤為帛、為囊，故曰組囊。艮為刀刃、為錐，軸方車不行，以囊盛錐必脫穎，二者皆不便也。坤為師旅，震為反，故曰還師。艮為兵革，艮止故休。○車，宋元本訛東，依汲古。</p><h3 id="無妄之益" tabindex="-1">無妄之益 <a class="header-anchor" href="#無妄之益" aria-label="Permalink to “無妄之益”">​</a></h3><h3 id="林辭-41" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-41" aria-label="Permalink to “林辭”">​</a></h3><p>魚擾水渴，桀亂我國。駕龍出遊，東之樂土。天賜我祿，與生為福。</p><h3 id="注-41" tabindex="-1">注 <a class="header-anchor" href="#注-41" aria-label="Permalink to “注”">​</a></h3><p>坤為魚、為水、為濁，震為擾，故曰魚擾水濁。坤為惡，故曰桀。坤為亂、為國，震為龍、為出遊、為東、為桀，坤為邑，故曰樂邑。伏乾為天、為祿、為福。○天賜我祿，汲古作&quot;尺賜我桀&quot;，今依宋元本。</p><h3 id="無妄之夬" tabindex="-1">無妄之夬 <a class="header-anchor" href="#無妄之夬" aria-label="Permalink to “無妄之夬”">​</a></h3><h3 id="林辭-42" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-42" aria-label="Permalink to “林辭”">​</a></h3><p>白虎黑狼，伏伺山陽。遮遏牛羊，病我商人。</p><h3 id="注-42" tabindex="-1">注 <a class="header-anchor" href="#注-42" aria-label="Permalink to “注”">​</a></h3><p>伏艮為虎狼，兌西方金，故曰白虎，坤色黑，故曰黑狼，艮止故曰伏伺、曰遮遏。艮為山陽，坤為牛，兌為羊，坤為病、為我，巽為商旅。○伏伺山陽，宋元本作&quot;伏司亦長&quot;，依汲古。</p><h3 id="無妄之姤" tabindex="-1">無妄之姤 <a class="header-anchor" href="#無妄之姤" aria-label="Permalink to “無妄之姤”">​</a></h3><h3 id="林辭-43" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-43" aria-label="Permalink to “林辭”">​</a></h3><p>履危不安，跌頓我顏，傷腫為瘢。伏震為履，巽殞落故曰不安、曰跌頓我顏。</p><h3 id="注-43" tabindex="-1">注 <a class="header-anchor" href="#注-43" aria-label="Permalink to “注”">​</a></h3><p>腫瘢，疑用《無妄》《艮》象。○瘢，宋元本作癩，依汲古。</p><h3 id="無妄之萃" tabindex="-1">無妄之萃 <a class="header-anchor" href="#無妄之萃" aria-label="Permalink to “無妄之萃”">​</a></h3><h3 id="林辭-44" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-44" aria-label="Permalink to “林辭”">​</a></h3><p>三人輦車，東入旁家。王母貪叨，盜我資財，亡失犂牛。</p><h3 id="注-44" tabindex="-1">注 <a class="header-anchor" href="#注-44" aria-label="Permalink to “注”">​</a></h3><p>對《大畜》。震為人、為車，震數三，故曰三人輦車。震為東，艮為家，巽為入，坤為母，對《乾》故曰王母，兌食故曰貪叨。互巽為盜，坤為資財、為亡失、為牛。○東，宋元本作乘，依汲古。</p><h3 id="無妄之升" tabindex="-1">無妄之升 <a class="header-anchor" href="#無妄之升" aria-label="Permalink to “無妄之升”">​</a></h3><h3 id="林辭-45" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-45" aria-label="Permalink to “林辭”">​</a></h3><p>三雁南飛，俱就塘池。鰕暼撓校利得過倍。</p><h3 id="注-45" tabindex="-1">注 <a class="header-anchor" href="#注-45" aria-label="Permalink to “注”">​</a></h3><p>震為雁、為南，數三，故曰三雁南飛。兌為塘池，坤巽皆為魚，故曰鰕暼撓小Ｙ鬮倍利。○塘池，宋元本作井地，茲依汲古。雁，汲古作鶴，依宋元本。</p><h3 id="無妄之困" tabindex="-1">無妄之困 <a class="header-anchor" href="#無妄之困" aria-label="Permalink to “無妄之困”">​</a></h3><h3 id="林辭-46" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-46" aria-label="Permalink to “林辭”">​</a></h3><p>鷹棲茂樹，候雀來往。一擊獲兩，利在枝柯。</p><h3 id="注-46" tabindex="-1">注 <a class="header-anchor" href="#注-46" aria-label="Permalink to “注”">​</a></h3><p>對《賁》。艮為鷹，震為茂樹，艮在震上，故曰鷹棲茂樹。離為雀，巽為進退、為往來。艮為擊，坎數一，故曰一擊。坎為獲，兌卦數二，故曰獲兩。巽為利、為枝柯，利在枝柯，言以枝柯為隱蔽也。○第四句宋元本作伏不枝梧，候作猴，茲依汲古。</p><h3 id="無妄之井" tabindex="-1">無妄之井 <a class="header-anchor" href="#無妄之井" aria-label="Permalink to “無妄之井”">​</a></h3><h3 id="林辭-47" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-47" aria-label="Permalink to “林辭”">​</a></h3><p>堯舜欽明，禹稷股肱。伊尹往來，進履登堂。顯德之徒，可以輔王。</p><h3 id="注-47" tabindex="-1">注 <a class="header-anchor" href="#注-47" aria-label="Permalink to “注”">​</a></h3><p>對《噬嗑》。震為帝，故曰堯舜。離為明，艮為臣，故曰禹稷、曰伊尹。巽為往來、為股肱，震為履、為進、為登，艮為堂，故進履登堂。艮貴為顯，震為王。○履，宋元本作禮，依汲古。</p><h3 id="無妄之革" tabindex="-1">無妄之革 <a class="header-anchor" href="#無妄之革" aria-label="Permalink to “無妄之革”">​</a></h3><h3 id="林辭-48" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-48" aria-label="Permalink to “林辭”">​</a></h3><p>枯旱三年，草萊不生。粢盛空乏，無以供靈。</p><h3 id="注-48" tabindex="-1">注 <a class="header-anchor" href="#注-48" aria-label="Permalink to “注”">​</a></h3><p>詳《需》林。○乏，元本訛之，依宋本、汲古。萊，宋元本作葉，依汲古。</p><h3 id="無妄之鼎" tabindex="-1">無妄之鼎 <a class="header-anchor" href="#無妄之鼎" aria-label="Permalink to “無妄之鼎”">​</a></h3><h3 id="林辭-49" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-49" aria-label="Permalink to “林辭”">​</a></h3><p>方口緩唇，為知樞門。解釋鉤帶，商旅以歡。</p><h3 id="注-49" tabindex="-1">注 <a class="header-anchor" href="#注-49" aria-label="Permalink to “注”">​</a></h3><p>兌為口，伏坤，故曰方口。兌又為唇，坤柔，故曰緩唇。伏坎為樞、為智，坤為門，言口舌為智慧之樞機也。震為解釋，巽為帶、為商旅，兌悅故歡。坎為矯輮，或為鉤。○首句宋本作口方緩唇，汲古作方口圓舌，依元本。知，宋元本作和，依汲古。</p><h3 id="無妄之震" tabindex="-1">無妄之震 <a class="header-anchor" href="#無妄之震" aria-label="Permalink to “無妄之震”">​</a></h3><h3 id="林辭-50" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-50" aria-label="Permalink to “林辭”">​</a></h3><p>鳧池水溢，高陸為海。江河橫流，魚鱉成市。千里無牆，鴛鳳遊行。</p><h3 id="注-50" tabindex="-1">注 <a class="header-anchor" href="#注-50" aria-label="Permalink to “注”">​</a></h3><p>震為鳧，坎為池、為水，艮為陸，四爻艮覆成坎，故高陸為海。又四爻上下皆重陰，而坤為河海故曰橫流。伏巽為魚、為市，艮為鱉、為牆，震為千里，艮覆故無牆。伏離為鴛鳳，震為遊行。○首句宋元本作鳧鷖池水，依汲古。</p><h3 id="無妄之艮" tabindex="-1">無妄之艮 <a class="header-anchor" href="#無妄之艮" aria-label="Permalink to “無妄之艮”">​</a></h3><h3 id="林辭-51" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-51" aria-label="Permalink to “林辭”">​</a></h3><p>烹魚失刀，駕車馬亡。錫刃不入，魴鯉腥臊。</p><h3 id="注-51" tabindex="-1">注 <a class="header-anchor" href="#注-51" aria-label="Permalink to “注”">​</a></h3><p>伏巽為魚，艮為刀，坎為矢，故曰失刀。震為車、為馬，坎隱故馬亡。艮為刃，下柔故曰錫刃。伏巽為魴鯉、為臭，故曰腥臊。又巽為入，巽伏故不入。○車馬，宋元作馬車。入，宋元作及。錫刃，宋元作鉛刀，均作［當作依］汲古。</p><h3 id="無妄之漸" tabindex="-1">無妄之漸 <a class="header-anchor" href="#無妄之漸" aria-label="Permalink to “無妄之漸”">​</a></h3><h3 id="林辭-52" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-52" aria-label="Permalink to “林辭”">​</a></h3><p>戎狄蹲踞，無禮貪叨。非吾族類，君子攸去。</p><h3 id="注-52" tabindex="-1">注 <a class="header-anchor" href="#注-52" aria-label="Permalink to “注”">​</a></h3><p>此用遇卦象。《無妄》伏坤為戎，狄震為箕，故曰蹲踞。蹲踞，即箕踞也。伏震兌皆為口，故曰貪叨。坤為禮、為族類，坤伏故曰無禮、曰非吾族類。艮為君子。</p><h3 id="無妄之歸妹" tabindex="-1">無妄之歸妹 <a class="header-anchor" href="#無妄之歸妹" aria-label="Permalink to “無妄之歸妹”">​</a></h3><h3 id="林辭-53" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-53" aria-label="Permalink to “林辭”">​</a></h3><p>渡河逾水，狐濡其尾，不為禍憂。捕魚遇蟹，利得無幾。</p><h3 id="注-53" tabindex="-1">注 <a class="header-anchor" href="#注-53" aria-label="Permalink to “注”">​</a></h3><p>坎為河、為水、為狐、為濡，伏艮為尾，坎為禍憂，震樂故不憂。伏巽為魚、為利，艮為蟹，言佔得此者雖無憂患而利得甚少也。○狐濡，宋元本作濡洿，今依汲古。</p><h3 id="無妄之豐" tabindex="-1">無妄之豐 <a class="header-anchor" href="#無妄之豐" aria-label="Permalink to “無妄之豐”">​</a></h3><h3 id="林辭-54" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-54" aria-label="Permalink to “林辭”">​</a></h3><p>河出小魚，不宜勞煩。苛政害民，君受其患。</p><h3 id="注-54" tabindex="-1">注 <a class="header-anchor" href="#注-54" aria-label="Permalink to “注”">​</a></h3><p>伏坎為河，巽為魚，兌小故曰小魚。坎為勞、為民、為患，震為君，言政苛害民而卒受患者仍在君也。○出，宋元本作水，害作苦，依汲古。</p><h3 id="無妄之旅" tabindex="-1">無妄之旅 <a class="header-anchor" href="#無妄之旅" aria-label="Permalink to “無妄之旅”">​</a></h3><h3 id="林辭-55" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-55" aria-label="Permalink to “林辭”">​</a></h3><p>偃武修文，兵革休安。清人遙逍，未歸空閑。</p><h3 id="注-55" tabindex="-1">注 <a class="header-anchor" href="#注-55" aria-label="Permalink to “注”">​</a></h3><p>震為武，震伏故曰偃武，禹在上故曰修文。艮為兵、為革，艮止故休。○未歸，汲古作來歸，依宋元本。清人，《詩鄭風》篇名，&quot;河上乎逍遙。&quot;</p><h3 id="無妄之巽" tabindex="-1">無妄之巽 <a class="header-anchor" href="#無妄之巽" aria-label="Permalink to “無妄之巽”">​</a></h3><h3 id="林辭-56" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-56" aria-label="Permalink to “林辭”">​</a></h3><p>九疑鬱林，沮濕不中。鸞鳥所去，君子不安。</p><h3 id="注-56" tabindex="-1">注 <a class="header-anchor" href="#注-56" aria-label="Permalink to “注”">​</a></h3><p>伏《震》，數九，坎為疑，震為叢木，故曰九疑鬱林，皆南方郡，震為南也。互坎故沮濕。震為鸞鳥，震往故曰去。艮為君子、為安，坎險故不安。○所，汲古作茲，從宋元本。</p><h3 id="無妄之兌" tabindex="-1">無妄之兌 <a class="header-anchor" href="#無妄之兌" aria-label="Permalink to “無妄之兌”">​</a></h3><h3 id="林辭-57" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-57" aria-label="Permalink to “林辭”">​</a></h3><p>搏猥逢虎，患厭不起。遂至歡國，與福笑語，君子樂喜。</p><h3 id="注-57" tabindex="-1">注 <a class="header-anchor" href="#注-57" aria-label="Permalink to “注”">​</a></h3><p>通《艮》。為虎、為搏，互坎蝟為患，蝟能伏虎，故患厭不起。艮為國，互震為歡、為笑語，艮為君子。○君子，宋元本作君王，依汲古。</p><h3 id="無妄之渙" tabindex="-1">無妄之渙 <a class="header-anchor" href="#無妄之渙" aria-label="Permalink to “無妄之渙”">​</a></h3><h3 id="林辭-58" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-58" aria-label="Permalink to “林辭”">​</a></h3><p>狗生龍馬，公勞嫗苦。家無善駒，折悔為吝。</p><h3 id="注-58" tabindex="-1">注 <a class="header-anchor" href="#注-58" aria-label="Permalink to “注”">​</a></h3><p>艮為狗，震為龍馬、為生，震為公，巽為嫗，坎為勞苦，故曰公勞嫗苦。艮為家，震為駒，坎為折。○善駒，汲古作筐筥，從宋元本。因震在艮下，故曰狗生龍馬。</p><h3 id="無妄之節" tabindex="-1">無妄之節 <a class="header-anchor" href="#無妄之節" aria-label="Permalink to “無妄之節”">​</a></h3><h3 id="林辭-59" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-59" aria-label="Permalink to “林辭”">​</a></h3><p>嬰孩求乳，慈母歸子。黃麑悅喜，得其甘餌。</p><h3 id="注-59" tabindex="-1">注 <a class="header-anchor" href="#注-59" aria-label="Permalink to “注”">​</a></h3><p>震為嬰孩，艮為乳、為求，故曰嬰孩求乳。伏巽為慈母，震為子、為歸，故曰慈母歸子。震為玄黃、為鹿，故曰黃麑，又為喜、為餌。</p><h3 id="無妄之中孚" tabindex="-1">無妄之中孚 <a class="header-anchor" href="#無妄之中孚" aria-label="Permalink to “無妄之中孚”">​</a></h3><h3 id="林辭-60" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-60" aria-label="Permalink to “林辭”">​</a></h3><p>有兩赤鷂，從五隼噪。操矢無筈，趣釋爾射。扶伏聽命，不敢動搖。</p><h3 id="注-60" tabindex="-1">注 <a class="header-anchor" href="#注-60" aria-label="Permalink to “注”">​</a></h3><p>艮為鷂、為隼，正覆艮，兌卦敷二，故曰兩鷂。巽卦數五，故曰五隼。兌納丁，故曰赤。艮為矢、為操。筈，箭未受弦處也。《兌》象也。艮矢在上卦，上卦兌覆故無筈。震為射，矢無筈則不能射，故釋不射也。艮為扶，巽為伏、為命，扶伏，即匍匐，伏地以手行也。艮震象也，動搖應作搖動，與命協。○筈，宋元本作括，射作財，茲從汲古。</p><h3 id="無妄之小過" tabindex="-1">無妄之小過 <a class="header-anchor" href="#無妄之小過" aria-label="Permalink to “無妄之小過”">​</a></h3><h3 id="林辭-61" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-61" aria-label="Permalink to “林辭”">​</a></h3><p>伊尹智士，去桀耕野。執順以強，天佑無咎。</p><h3 id="注-61" tabindex="-1">注 <a class="header-anchor" href="#注-61" aria-label="Permalink to “注”">​</a></h3><p>震為士、為耕，兌剛魯故曰桀，艮手為執，巽順故曰執順。震為強健，艮為天。○天佑，宋元本作文和，茲依汲古。</p><h3 id="無妄之既濟" tabindex="-1">無妄之既濟 <a class="header-anchor" href="#無妄之既濟" aria-label="Permalink to “無妄之既濟”">​</a></h3><h3 id="林辭-62" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-62" aria-label="Permalink to “林辭”">​</a></h3><p>逐鹿西山，利入我門。陰陽和調，國無災殃。</p><h3 id="注-62" tabindex="-1">注 <a class="header-anchor" href="#注-62" aria-label="Permalink to “注”">​</a></h3><p>《無妄》艮為鹿、為山、為門，震為逐，巽為利、為入，《既濟》陰陽平均，六爻當位，故曰陰陽調和。○各本下多&quot;長子東遊，須其三仇&quot;八字，與上文義不協，汲古註曰疑衍文，故不錄。</p><h3 id="無妄之未濟" tabindex="-1">無妄之未濟 <a class="header-anchor" href="#無妄之未濟" aria-label="Permalink to “無妄之未濟”">​</a></h3><h3 id="林辭-63" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-63" aria-label="Permalink to “林辭”">​</a></h3><p>龍興之德，周武受福。長女宜家，與君相保。長股遠行，狸且善藏。</p><h3 id="注-63" tabindex="-1">注 <a class="header-anchor" href="#注-63" aria-label="Permalink to “注”">​</a></h3><p>《無妄》震為龍、為德、為周、為武、為君，巽為長女、為長股、為藏，艮為家、為狸。○受，汲古作成，保作德，均依宋元本。</p>',322)])])}const m=e(l,[["render",n]]);export{p as __pageData,m as default};
